import React from 'react';
import { Alert, Box, Button, Stack, Typography } from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import WorkspacePageHeader from './shared/WorkspacePageHeader';
import { PLAN_UPGRADE_CONTACT_EMAIL } from '../constants/subscriptionPlans';

/**
 * Shown when `/billing` is opened while subscription checkout is disabled.
 * Avoids silently dumping users onto Home (CI-BUG-041).
 */
const BillingUnavailablePage: React.FC = () => (
  <Box>
    <WorkspacePageHeader
      title="Billing"
      description="Subscription checkout is not enabled for this workspace yet."
    />
    <Alert severity="info" sx={{ mb: 2 }}>
      Online plan purchase is currently turned off. Your workspace stays available — contact us if you need a paid plan
      or invoice.
    </Alert>
    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
      Email{' '}
      <Box component="a" href={`mailto:${PLAN_UPGRADE_CONTACT_EMAIL}`} sx={{ color: 'primary.main' }}>
        {PLAN_UPGRADE_CONTACT_EMAIL}
      </Box>{' '}
      for billing questions.
    </Typography>
    <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1.5}>
      <Button component={RouterLink} to="/dashboard" variant="contained">
        Back to dashboard
      </Button>
      <Button component={RouterLink} to="/pricing" variant="outlined">
        View pricing overview
      </Button>
    </Stack>
  </Box>
);

export default BillingUnavailablePage;
